DROP TABLE IF EXISTS `advertisement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `advertisement` (
  `advertisement_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `image_data` mediumblob NOT NULL,
  `image_mime_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `position` enum('hero','promotion') COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`advertisement_id`),
  KEY `advertisement_display_idx` (`position`,`is_active`,`sort_order`,`advertisement_id`),
  CONSTRAINT `advertisement_active_chk` CHECK ((`is_active` in (0,1))),
  CONSTRAINT `advertisement_image_chk` CHECK ((length(`image_data`) > 0)),
  CONSTRAINT `advertisement_mime_chk` CHECK ((`image_mime_type` in (_utf8mb4'image/jpeg',_utf8mb4'image/png',_utf8mb4'image/webp',_utf8mb4'image/gif',_utf8mb4'image/avif',_utf8mb4'image/bmp'))),
  CONSTRAINT `advertisement_sort_chk` CHECK ((`sort_order` >= 0)),
  CONSTRAINT `advertisement_title_chk` CHECK ((char_length(trim(`title`)) between 1 and 200))
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
