DROP TABLE IF EXISTS `coupons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `coupons` (
  `coupon_id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(50) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `discount_type` enum('percent','fixed') COLLATE utf8mb4_unicode_ci NOT NULL,
  `discount_value` decimal(12,2) NOT NULL,
  `min_order_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `max_discount_amount` decimal(12,2) DEFAULT NULL,
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `max_uses` int DEFAULT NULL,
  `used_count` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`coupon_id`),
  UNIQUE KEY `uq_coupons_code` (`code`),
  CONSTRAINT `coupons_active_chk` CHECK ((`is_active` in (0,1))),
  CONSTRAINT `coupons_code_length_chk` CHECK ((char_length(`code`) between 3 and 50)),
  CONSTRAINT `coupons_dates_chk` CHECK ((`ends_at` > `starts_at`)),
  CONSTRAINT `coupons_discount_value_chk` CHECK (((`discount_value` > 0) and ((`discount_type` <> _utf8mb4'percent') or (`discount_value` <= 100)))),
  CONSTRAINT `coupons_max_discount_chk` CHECK (((`max_discount_amount` is null) or ((`discount_type` = _utf8mb4'percent') and (`max_discount_amount` > 0)))),
  CONSTRAINT `coupons_min_order_chk` CHECK ((`min_order_amount` >= 0)),
  CONSTRAINT `coupons_uses_chk` CHECK (((`used_count` >= 0) and ((`max_uses` is null) or ((`max_uses` > 0) and (`used_count` <= `max_uses`)))))
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
